#!/usr/bin/env python3
"""Pipeline : lit les données Garmin, calcule l'analyse, génère le dashboard HTML interactif,
la version chiffrée pour publication et le résumé HTML du mail.
Usage : python build_dashboard.py [--src garmin] [--out dist]
Variables d'environnement : DASHBOARD_PASSWORD (chiffre index.html), DASHBOARD_URL (lien dans le mail)."""
import argparse, base64, hashlib, json, os, sys
from datetime import date, datetime
from pathlib import Path

import config
import coach_memory
import plan_adapt
import goals as goals_mod
import mail_ui as U
import pain as pain_mod
from analysis import PLAB, build_analysis, f1, pace, sgn
from garmin_data import load_all

try:
    from zoneinfo import ZoneInfo
    NOW = datetime.now(ZoneInfo("Europe/Paris"))
except Exception:
    NOW = datetime.now()
MOIS = ["janvier", "février", "mars", "avril", "mai", "juin", "juillet", "août", "septembre", "octobre", "novembre", "décembre"]
HERE = Path(__file__).resolve().parent
VERSION = "v3"


def date_fr(d):
    dt = date.fromisoformat(d)
    return f"{dt.day} {MOIS[dt.month - 1]} {dt.year}"


def clean(o):
    """Remplace NaN/inf par None (JSON strict) et force les clés en texte, récursivement."""
    if isinstance(o, float):
        return o if o == o and o not in (float("inf"), float("-inf")) else None
    if isinstance(o, dict):
        return {str(k): clean(v) for k, v in o.items()}
    if isinstance(o, (list, tuple, set)):
        return [clean(v) for v in o]
    return o


def render_dashboard(acts, days, A, goals_edit=None, pains=None):
    keys = ("d", "s", "km", "m", "hr", "el", "ld", "te", "vo2", "nm", "pw")
    data = {"today": A["today"], "gen": NOW.strftime("%d/%m/%Y %H:%M"),
            "acts": [{k: (round(a[k], 2) if isinstance(a[k], float) else a[k]) for k in keys} for a in acts],
            "days": days, "A": A, "cfg": config.ATHLETE,
            "gh": goals_mod.DEFAULT_GITHUB, "goals_edit": goals_mod.to_edit(goals_edit or []),
            "pains_edit": pains or [], "pain_cat": pain_mod.catalog()}
    data = clean(data)
    blob = json.dumps(data, ensure_ascii=False, default=str, allow_nan=False).replace("</", "<\\/")
    tpl = (HERE / "dashboard_template.html").read_text(encoding="utf-8")
    return tpl.replace("/*__DATA__*/null/*__END__*/", blob)


# Application installable (PWA) : balises ajoutées à la page publiée (écran de verrouillage + dashboard déchiffré).
PWA_HEAD = ('<link rel="manifest" href="manifest.webmanifest">'
            '<link rel="icon" type="image/png" sizes="32x32" href="favicon-32.png">'
            '<link rel="apple-touch-icon" href="icon-180.png">'
            '<meta name="apple-mobile-web-app-capable" content="yes"><meta name="mobile-web-app-capable" content="yes">'
            '<meta name="apple-mobile-web-app-title" content="Emberline"><meta name="application-name" content="Emberline">'
            '<meta name="apple-mobile-web-app-status-bar-style" content="default">')
PWA_DIR = HERE / "pwa"


def add_pwa(html):
    """Insère les balises PWA juste avant </head> (une seule fois)."""
    if 'rel="manifest"' in html or "</head>" not in html:
        return html
    return html.replace("</head>", PWA_HEAD + "</head>", 1)


LOCK = r'''<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="color-scheme" content="light dark"><meta name="robots" content="noindex"><title>Emberline</title>
<meta name="theme-color" content="#EDE8E0" media="(prefers-color-scheme: light)"><meta name="theme-color" content="#17130F" media="(prefers-color-scheme: dark)">
<style>:root{--bg:#EDE8E0;--card:#F5F0E8;--ink:#17130F;--sub:#6F6962;--em:#CF7230;--emt:#905225;--line:rgba(23,19,15,.14)}@media(prefers-color-scheme:dark){:root{--bg:#17130F;--card:#24201C;--ink:#F5F0E8;--sub:#A8A29B;--emt:#DA9867;--line:rgba(245,240,232,.16)}}
body{margin:0;min-height:100vh;display:flex;align-items:center;justify-content:center;background:var(--bg);color:var(--ink);font:16px -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",Arial,sans-serif}
.c{background:var(--card);border-radius:24px;padding:36px 32px;width:min(360px,88vw);text-align:center;border:1px solid var(--line);box-shadow:0 18px 50px -20px rgba(23,19,15,.35)}
h1{margin:4px auto 16px;width:min(240px,74%);aspect-ratio:4.5238;background:var(--ink);-webkit-mask:url(data:image/png;base64,) center/contain no-repeat;mask:url(data:image/png;base64,) center/contain no-repeat;font-size:0;color:transparent;overflow:hidden}p{color:var(--sub);font-size:14px;margin:0 0 20px}
input[type=password]{width:100%;box-sizing:border-box;padding:13px 14px;border-radius:12px;border:1.5px solid var(--line);background:transparent;color:inherit;font-size:16px;outline:0}input[type=password]:focus{border-color:var(--em)}
button{width:100%;margin-top:12px;padding:13px;border:0;border-radius:12px;background:var(--em);color:#17130F;font-size:16px;font-weight:700;cursor:pointer}button:hover{filter:brightness(1.06)}
label{display:flex;gap:8px;align-items:center;justify-content:center;margin-top:14px;font-size:13px;color:var(--sub)}label input{accent-color:var(--em)}#e{color:var(--emt);font-size:13px;min-height:18px;margin-top:10px}</style></head>
<body><form class="c" id="f"><h1 role="img" aria-label="Emberline">Emberline</h1><p>Dashboard privé : saisis le mot de passe.</p>
<input id="pw" type="password" placeholder="Mot de passe" autocomplete="current-password" autofocus><button>Déverrouiller</button>
<label><input type="checkbox" id="rm"> Mémoriser sur cet appareil</label><div id="e"></div></form>
<script>
if("serviceWorker" in navigator&&location.protocol!=="file:")navigator.serviceWorker.register("sw.js").catch(()=>{});
const P=__PAYLOAD__;const b64=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));
async function dec(pw){const k0=await crypto.subtle.importKey("raw",new TextEncoder().encode(pw),"PBKDF2",false,["deriveKey"]);
const k=await crypto.subtle.deriveKey({name:"PBKDF2",salt:b64(P.s),iterations:P.i,hash:"SHA-256"},k0,{name:"AES-GCM",length:256},false,["decrypt"]);
return new TextDecoder().decode(await crypto.subtle.decrypt({name:"AES-GCM",iv:b64(P.v)},k,b64(P.c)))}
async function go(pw,remember){try{const h=await dec(pw);if(remember)try{localStorage.setItem("gd_pw",pw)}catch(e){}document.open();document.write(h);document.close()}
catch(e){document.getElementById("e").textContent="Mot de passe incorrect.";try{localStorage.removeItem("gd_pw")}catch(_){}}}
document.getElementById("f").addEventListener("submit",e=>{e.preventDefault();go(document.getElementById("pw").value,document.getElementById("rm").checked)});
try{const s=localStorage.getItem("gd_pw");if(s)go(s,true)}catch(e){}
</script></body></html>'''


def encrypt_page(page_html, password):
    page_html = add_pwa(page_html)                              # garde le manifeste après déchiffrement (bouton « Installer »)
    from cryptography.hazmat.primitives.ciphers.aead import AESGCM
    salt, iv, iters = os.urandom(16), os.urandom(12), 250000
    key = hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), salt, iters, 32)
    ct = AESGCM(key).encrypt(iv, page_html.encode("utf-8"), None)
    b = lambda x: base64.b64encode(x).decode()
    return add_pwa(LOCK).replace("__PAYLOAD__", json.dumps({"s": b(salt), "v": b(iv), "c": b(ct), "i": iters}))


def memoriser_plan(A, plan_mem, path, today):
    """Conserve les séances conseillées du jour (non affichées) pour le bilan hebdomadaire des jours suivants ; sans effet visible si l'écriture échoue."""
    plog = A.get("suggest", {}).pop("plan_log", None)
    try:
        plan_adapt.save(path, plan_adapt.merge(plan_mem, date.fromisoformat(today), plog or {}))
    except (OSError, ValueError, TypeError) as e:
        print(f"Mémoire du plan non enregistrée ({type(e).__name__}) : sans effet sur le dashboard.")


def fire_label(sc, fallback=""):
    """Libellé affiché de la note sur 20, dans le thème Emberline (affichage seulement : le calcul et score_label restent inchangés)."""
    if sc is None:
        return fallback
    return "En feu" if sc >= 17 else "Bouillant" if sc >= 14 else "Ça chauffe" if sc >= 11 else "Tiède" if sc >= 8 else "Refroidi"


def build_email(A, url):
    """Mail quotidien : bilan de la semaine, mise en page commune avec le dashboard (voir mail_ui.py). Les repères <!--SUBJECT--> et <!--WARN--> sont lus par send_mail.py."""
    S = A["stats"]["1S"]["cur"]; Sp = A["stats"]["1S"]["prev"]; sy = A["synth"]["1S"]; r = S["run"]; rc = S["rec"]
    PP = A["pillars_p"]["1S"]; sc = PP["score"]
    col = {"green": U.GREEN, "orange": U.ORANGE, "red": U.RED}.get(PP.get("tone"), "#8E8E93")
    pil = ""
    for p in PP["pillars"]:
        v = p["score"]; pc = {"green": U.GREEN, "orange": U.ORANGE, "red": U.RED}.get(p.get("tone"), "#8E8E93")
        pil += (f'<tr><td class="m-ink" style="padding:6px 0 3px;font-size:13.5px;color:{U.INK};font-weight:600">{U.esc(p["name"])}</td>'
                f'<td class="m-sub" style="text-align:right;font-size:13px;color:{U.SUB};white-space:nowrap;padding-left:8px">{"n/a" if v is None else f1(v) + " / 4"}</td></tr>'
                f'<tr><td colspan="2" style="padding-bottom:3px">{U.bar(v, pc)}</td></tr>')
    dh = f" ({sgn((S['h'] - Sp['h']) / Sp['h'] * 100)})" if Sp and Sp["h"] else ""
    kp = [("Séances", f"{S['n']}", f"{f1(S['h'])} h{dh}"), ("Course", f"{f1(r['km'])} km", f"{r['n']} sortie(s)" + (f" · {pace(r['pace'])}/km" if r["pace"] else "")),
          ("Charge", f"{S['ld']:.0f}", f"ratio {f1(S['acwr'], 2) if S['acwr'] else 'n/a'}"), ("Sommeil", f"{rc['sc']:.0f}/100" if rc["sc"] is not None else "–", f"{f1(rc['sh'])} h" if rc["sh"] else ""),
          ("VFC", f"{rc['hrv']:.0f} ms" if rc["hrv"] else "–", f"FC repos {rc['rhr']:.0f}" if rc["rhr"] else ""), ("Readiness", f"{rc['tr']:.0f}" if rc["tr"] else "–", f"Body Battery max {rc['bbx']:.0f}" if rc["bbx"] else "")]
    if url:
        btn = (U.button(url, "Ouvrir le dashboard interactif") +
               f'<div class="m-sub" style="font-size:12px;color:{U.SUB};margin-top:10px;text-align:center">Bascule 1 semaine / 1 mois / 3 mois dans la page (mot de passe demandé).</div>')
    else:
        btn = f'<div class="m-sub" style="font-size:12.5px;color:{U.SUB};text-align:center">Lien du dashboard interactif non configuré (voir les secrets SITE_PUSH_TOKEN et DASHBOARD_PASSWORD).</div>'
    bl = ((A.get("bilan") or {}).get("1S") or {}).get("text")
    coach = U.card(U.title(f"Le mot du coach · {PLAB['1S']}") + f'<div class="m-ink" style="font-size:16px;line-height:1.55;color:{U.INK}">{U.esc(bl)}</div>', "#7864FF") if bl else ""
    fr = A.get("fresh") or {}
    warn_html = U.card(f'<div class="m-ink" style="font-size:14px;line-height:1.5;color:{U.INK}"><b>⚠ Données datées</b><br>{U.esc(fr["message"])}</div>',
                       U.RED if fr.get("level") == "alert" else U.ORANGE) if fr.get("message") else ""
    pn = A.get("pain") or {}
    pain_html = U.card(U.title("Douleurs prises en compte", U.RED) + U.bullets([x["title"] for x in pn.get("panel", [])][:4], U.RED), U.RED) if pn.get("any") else ""
    warn_mark = f"<!--WARN: {fr['message'].replace('--', '-')}-->" if fr.get("message") else ""
    subject = f"Performance : {f1(sc) if sc is not None else '–'}/20 · {NOW.strftime('%d/%m/%Y')}"
    score = U.card(f'<table role="presentation" width="100%" cellspacing="0" cellpadding="0"><tr><td style="width:150px;vertical-align:middle">'
                   f'<div style="font-size:54px;font-weight:700;letter-spacing:-.04em;color:{col};line-height:1">{f1(sc) if sc is not None else "–"}<span class="m-sub" style="font-size:20px;color:{U.SUB}">/20</span></div>'
                   f'<div style="font-size:15px;font-weight:650;color:{col};margin-top:2px">{U.esc(fire_label(sc, PP["label"]))}</div></td>'
                   f'<td style="vertical-align:middle"><table role="presentation" width="100%" cellspacing="0" cellpadding="0">{pil}</table></td></tr></table>', col)
    synth = U.card(U.title("Synthèse · " + PLAB["1S"]) + f'<div class="m-ink" style="font-size:15.5px;line-height:1.55;color:{U.INK}">{U.esc(sy["head"])}</div>')
    body = (U.header("Triathlon · course à pied", f"Bilan du {date_fr(A['today'])}") + warn_html + pain_html + coach + score + synth
            + U.card(U.title("Points forts", U.GREEN) + U.bullets(sy["good"], U.GREEN), U.GREEN)
            + U.card(U.title("Points à améliorer", U.ORANGE) + U.bullets(sy["bad"], U.ORANGE), U.ORANGE)
            + U.card(U.title("Focus course à pied", U.RUN) + U.bullets(sy["focus"], U.RUN), U.RUN)
            + U.card(U.title("Indicateurs clés") + U.tiles(kp), pad="16px 16px 12px")
            + f'<div style="padding:10px 0 18px">{btn}</div>' + U.footer("garmin-dashboard " + VERSION))
    return f"<!--SUBJECT: {subject}-->{warn_mark}" + U.wrap(body, f"Note {f1(sc) if sc is not None else '–'}/20 · {fire_label(sc, PP['label'])}")


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--src", type=Path, default=Path("garmin"))
    ap.add_argument("--out", type=Path, default=Path("dist"))
    ap.add_argument("--today", default=NOW.date().isoformat())
    a = ap.parse_args()
    if not a.src.exists():
        sys.exit(f"Dossier introuvable : {a.src}")
    acts, days, stats = load_all(a.src)
    print(f"garmin-dashboard {VERSION} · analyse déterministe")
    print(f"Fichiers lus : {stats.get('fichiers', 0)} | activités : {len(acts)} | jours : {len(days)}")
    if not acts and not days:
        sys.exit("Aucune donnée reconnue dans " + str(a.src))
    meta = {}
    try:
        meta = json.loads((a.src / "sync_status.json").read_text(encoding="utf-8"))
    except (OSError, ValueError):
        pass
    G, gwarn, gsrc = goals_mod.load_goals(Path(__file__).resolve().parent, config.GOALS)
    for w in gwarn: print("Objectifs :", w)
    print(f"Objectifs : {len(G)} (source : {gsrc})")
    P, pwarn = pain_mod.load(Path(__file__).resolve().parent)
    for w in pwarn: print("Douleurs :", w)
    print(f"Douleurs : {sum(1 for p in P if not p['archived'] and p['intensity'] > 0)} active(s), {sum(1 for p in P if p['archived'])} archivée(s)")
    mem_path = a.src / "coach_memory.json"                      # mémoire anti-répétition du mot du coach (versionnée avec les données)
    mem = coach_memory.load(mem_path)
    plan_path = a.src / "plan_memory.json"                      # séances conseillées des derniers jours : bilan hebdomadaire en tâche de fond (plan_adapt.py)
    plan_mem = plan_adapt.load(plan_path)
    A = build_analysis(acts, days, a.today, G, config.ATHLETE, config.PERIODS, events=getattr(config, "EVENTS", []), meta=meta, coach_mem=mem, pains=P, plan_mem=plan_mem)
    memoriser_plan(A, plan_mem, plan_path, a.today)
    try:
        coach_memory.save(mem_path, coach_memory.merge(mem, date.fromisoformat(a.today), {p: A["bilan"][p]["text"] for p in config.PERIODS}))
    except (OSError, ValueError, KeyError) as e:
        print(f"Mémoire du coach non enregistrée ({type(e).__name__}) : sans effet sur le dashboard.")
    if A["fresh"]["level"]:
        print("ATTENTION :", A["fresh"]["message"])
    a.out.mkdir(parents=True, exist_ok=True)
    page = render_dashboard(acts, days, A, G, P)
    (a.out / "dashboard.html").write_text(page, encoding="utf-8")
    pw = os.environ.get("DASHBOARD_PASSWORD", "")
    if pw:
        (a.out / "index.html").write_text(encrypt_page(page, pw), encoding="utf-8")
        print("Page chiffrée générée : index.html")
        if PWA_DIR.is_dir():
            n = 0
            for f in sorted(PWA_DIR.iterdir()):
                if f.is_file() and not f.name.startswith("."):
                    (a.out / f.name).write_bytes(f.read_bytes()); n += 1
            print(f"Fichiers d'application (PWA) copiés : {n}")
        else:
            print("Dossier pwa/ absent : page publiée sans mode application.")
    else:
        print("DASHBOARD_PASSWORD absent : pas de page chiffrée (publication impossible).")
    (a.out / "email_summary.html").write_text(build_email(A, os.environ.get("DASHBOARD_URL", "")), encoding="utf-8")
    print(f"Dashboard généré dans {a.out}/ · note globale : {f1(A['score']) if A['score'] is not None else 'n/a'}/20")


if __name__ == "__main__":
    main()
